<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Bouncing Ball Playground</title>
<style>
  :root{
    --bg:#0b0d12;
    --panel:#141822;
    --panel2:#1c2230;
    --ink:#e7ecf5;
    --muted:#8b96ab;
    --accent:#4dd6ff;
    --accent2:#ff6b9d;
  }
  *{box-sizing:border-box}
  html,body{height:100%}
  body{
    margin:0;
    background:radial-gradient(1200px 700px at 50% -10%, #17203a 0%, var(--bg) 60%);
    color:var(--ink);
    font:15px/1.5 ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
    display:flex;
    flex-direction:column;
    align-items:center;
    justify-content:center;
    min-height:100%;
    padding:24px 16px 32px;
    -webkit-font-smoothing:antialiased;
  }
  h1{
    margin:0 0 2px;
    font-size:20px;
    letter-spacing:.5px;
    font-weight:650;
  }
  .sub{
    margin:0 0 16px;
    color:var(--muted);
    font-size:13px;
    text-align:center;
  }
  .stage{
    padding:12px;
    background:linear-gradient(180deg,var(--panel2),var(--panel));
    border:1px solid #262e3f;
    border-radius:16px;
    box-shadow:0 20px 60px rgba(0,0,0,.55), inset 0 1px 0 rgba(255,255,255,.04);
  }
  #sim{
    display:block;
    width:640px;
    height:480px;
    max-width:86vw;
    border-radius:10px;
    background:#0a0c11;
    cursor:crosshair;
    touch-action:none;
    border:1px solid #2b3purple;
    border:1px solid #2b3348;
  }
  .controls{
    display:flex;
    gap:10px;
    flex-wrap:wrap;
    justify-content:center;
    margin-top:16px;
  }
  button{
    appearance:none;
    border:1px solid #33405a;
    background:linear-gradient(180deg,#232c3e,#1a2130);
    color:var(--ink);
    font:600 14px/1 inherit;
    letter-spacing:.3px;
    padding:11px 20px;
    border-radius:10px;
    cursor:pointer;
    transition:transform .08s ease, border-color .15s ease, background .15s ease, box-shadow .15s ease;
    box-shadow:0 4px 14px rgba(0,0,0,.35), inset 0 1px 0 rgba(255,255,255,.05);
  }
  button:hover{border-color:var(--accent);box-shadow:0 6px 18px rgba(77,214,255,.18), inset 0 1px 0 rgba(255,255,255,.07)}
  button:active{transform:translateY(1px) scale(.985)}
  button.primary{background:linear-gradient(180deg,#1d4d63,#143c4f);border-color:#2b7f9e}
